#!/usr/bin/env bash
# Regression test for tests/check_census_partition.sh. The gate's value is that
# it reads the two sources independently, so the pair it must distinguish is a
# census whose numbers reproduce (green) against the same census with one digit
# moved, one act dropped from the line, and a sum that no longer adds to the
# record count (each red, naming the drifted number). Missing inputs are the
# third state: no joined data means not applicable, no census means failure.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later

set -u

root=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  census-partition self-test (no git checkout)\n'
    exit 0
}
check=$root/tests/check_census_partition.sh
if [ ! -f "$check" ]; then
    printf 'FAIL  missing %s\n' "$check" >&2
    exit 1
fi

# Not a bare /tmp: MSYS child shells default TMP/TEMP to /tmp, and native
# git.exe then maps a /tmp argument to C:\tmp while bash sees %TEMP%.
if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -w "$USERPROFILE")
else
    tmpbase=${TMPDIR:-/tmp}
fi
tmp=$(mktemp -d "$tmpbase/pime-census-partition-selftest.XXXXXX")
sandbox=$tmp/repo
mkdir -p "$sandbox/docs/research" "$sandbox/.scratch/upstream-bugs"

cleanup() {
    rm -rf "$tmp"
}
trap cleanup EXIT

git -C "$sandbox" init -q >/dev/null || {
    printf 'git init failed in sandbox\n' >&2
    exit 1
}

census=$sandbox/docs/research/census.md
joined=$sandbox/.scratch/upstream-bugs/joined.json

failures=0

# expect <want> <name> — runs the gate over the two sandbox files.
expect() {
    local want=$1 name=$2 out got
    out=$(cd "$sandbox" && bash "$check" docs/research/census.md .scratch/upstream-bugs/joined.json 2>&1)
    got=$?
    if [ "$got" -ne "$want" ]; then
        printf 'FAIL  %s (exit %s, want %s)\n%s\n' "$name" "$got" "$want" "$out"
        failures=$((failures + 1))
    fi
}

# expect_says <name> <fragment> — the drift has to be named, not just red.
expect_says() {
    local name=$1 fragment=$2 out
    out=$(cd "$sandbox" && bash "$check" docs/research/census.md .scratch/upstream-bugs/joined.json 2>&1)
    case "$out" in
        *"$fragment"*) : ;;
        *) printf 'FAIL  %s (no "%s" in output)\n%s\n' "$name" "$fragment" "$out"
           failures=$((failures + 1)) ;;
    esac
}

# Four records over three acts and two statuses; the census quotes exactly these.
write_joined() {
    cat > "$joined" <<'JSON'
[
  {
    "n": 1,
    "status": "libchewing-upstream",
    "act": "upstream-lib"
  },
  {
    "n": 2,
    "status": "likely-fixed",
    "act": "close-out"
  },
  {
    "n": 3,
    "status": "likely-fixed",
    "act": "close-out"
  },
  {
    "n": 4,
    "status": "needs-windows-repro",
    "act": "needs-windows"
  },
  {
    "n": 5,
    "status": "stale-unreproducible",
    "act": "close-out"
  }
]
JSON
}

write_census() {
    cat > "$census" <<'MD'
# Census

## 2. Status verdicts

| status | n | meaning |
| --- | --- | --- |
| likely-fixed | 2 | closed after a retest |
| libchewing-upstream | 1 | root cause in the library |
| needs-windows-repro | 1 | needs a live desktop |
| stale-unreproducible | 1 | no retest thread left |

`act` (what should happen): close-out 3, needs-windows 1, **fixable-here 0**,
upstream-lib 1, dead 0.

## 4. Close-out pile

### 4.5 Stale unreproducible (1)
The stale issue (#5) plus a comment id.

| # | comment id |
| --- | --- |
| 5 | 12345 |

## 8. Method

- Partition of the records — the numbers §2 quotes:
  `jq -r` over the joined data
  gives needs-windows 1 (1 `needs-windows-repro`),
  close-out 3 (2 likely-fixed, 1 stale-unreproducible), dead 0,
  upstream-lib 1, fixable-here 0; 3+1+0+1+0 = 5.
MD
}

write_joined
write_census
expect 0 'a census that reproduces the joined data is green'

# One digit moved in the status table reddens it and names the status.
sed -E 's/^\| likely-fixed \| 2 \|/| likely-fixed | 3 |/' "$census" > "$census.n" && mv "$census.n" "$census"
expect 1 'a status count off by one reddens'
expect_says 'the drifted status is named' 'likely-fixed'

# The act line is read independently of the table.
write_census
expect 0 'restoring the census goes green again'
sed -E 's/^upstream-lib 1, dead 0\./upstream-lib 2, dead 0./' "$census" > "$census.n" && mv "$census.n" "$census"
expect 1 'an act count off by one reddens'
expect_says 'the drifted act is named' 'act upstream-lib'

# An act missing from the line is its own failure.
write_census
sed -E 's/^upstream-lib 1, dead 0\./dead 0./' "$census" > "$census.n" && mv "$census.n" "$census"
expect 1 'an act missing from the act line reddens'
expect_says 'the missing act is named' 'upstream-lib never quoted'

# A sum that no longer adds to the record count reddens too.
write_census
sed -E 's/3\+1\+0\+1\+0 = 5\./3+1+0+1+0 = 4./' "$census" > "$census.n" && mv "$census.n" "$census"
expect 1 'a sum line that misses the record count reddens'
expect_says 'the sum drift is named' 'joined data holds 5 records'

# The §4.5 stale set: the issue numbers the section names, against the joined
# data's stale-unreproducible records.
write_census
sed -E 's/The stale issue \(#5\)/The stale issue (#6)/' "$census" > "$census.n" && mv "$census.n" "$census"
expect 1 'a §4.5 issue number off the joined data reddens'
expect_says 'the stale set drift is named' '§4.5 stale set differs from the joined data'

# The comment-id table has to cover the named issues, one row each.
write_census
sed -E 's/^\| 5 \| 12345 \|/| 5 | 12345 | 6 | 67890 |/' "$census" > "$census.n" && mv "$census.n" "$census"
expect 1 'a comment-id table row the section does not name reddens'
expect_says 'the table drift is named' 'comment-id table'

# A census without a §4.5 section skips the stale comparison.
write_census
sed -E '/^### 4\.5 /,/^## 8\./d' "$census" > "$census.n" && mv "$census.n" "$census"
expect 0 'a census without a §4.5 section skips the stale comparison'

# Missing inputs: the joined data is git-excluded, the census is tracked.
write_census
mv "$joined" "$joined.keep"
expect 125 'no joined data is not applicable'
mv "$joined.keep" "$joined"
rm -f "$census"
expect 1 'no census is a failure'

printf '%d failed\n' "$failures"
[ "$failures" -eq 0 ]
